input.old_string:
.board-pagination-controls {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  gap: 0.4rem;
  width: 100%;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scrollbar-width: none;
}

.board-pagination-controls::-webkit-scrollbar {
  display: none;
}

.filter-btn.board-page-nav {
  flex: 1 1 5rem;
  min-width: 0;
  justify-content: center;
  padding-inline: 0.65rem;
}

.filter-btn.board-page-num {
  flex: 0 0 var(--control-height);
  width: var(--control-height);
  min-width: var(--control-height);
  padding-inline: 0;
}

input.new_string:
.board-pagination-controls {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  gap: 0.4rem;
  width: 100%;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
}

.board-pagination-controls::-webkit-scrollbar {
  display: none;
}

.filter-btn.board-page-nav {
  flex: 0 0 auto;
  justify-content: center;
  padding-inline: 0.75rem;
}

.filter-btn.board-page-num {
  flex: 0 0 var(--control-height);
  box-sizing: border-box;
  width: var(--control-height);
  min-width: var(--control-height);
  max-width: var(--control-height);
  padding-inline: 0;
}
